<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Add User</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body class="bg-light"><div class="container py-5"><?= view('partials/navigation') ?><div class="card shadow-sm mx-auto" style="max-width:640px"><div class="card-body"><h1 class="h3 mb-4">Add New User</h1>
